+    public static void main(String[] args) throws Exception {
+        try {
+            KafkaUtils kafkaUtils = new KafkaUtils();
+            if (kafkaUtils.isReadEnabled()) {
+                kafkaUtils.initKafkaConsumer();
+            }
+
+            if (kafkaUtils.isWriteEnabled()) {
+                kafkaUtils.initKafkaProducer();
+            }
