+        if (kafkaTopic == null || kafkaTopic.isEmpty()) {
+            loggerMaker.errorAndAddToDb("AKTO_KAFKA_TOPIC_NAME env var is required", LoggerMaker.LogDb.RUNTIME);
+            System.exit(1);
