+            try {
+                FilterConfig apiFilter = apiFilterEntry.getValue();
+                Map<String, Object> varMap = apiFilter.resolveVarMap();
+                VariableResolver.resolveWordList(varMap, new HashMap<ApiInfoKey, List<String>>() {
