+
+        if (useHostCondition(hostName, httpResponseParam.getSource())) {
+            hostName = hostName.toLowerCase();
+            hostName = hostName.trim();
+
+            String key = hostName;
+            boolean ismcpServer = false;
+
+            if (hostNameToIdMap.containsKey(key)) {
