+        // Calculate network range
+        byte[] addr = baseAddress.getAddress();
+        int baseInt = bytesToInt(addr);
+        int mask = (-1) << (32 - prefixLength);
+        int start = baseInt & mask;
+        int end = start | (~mask);
+        
+        // Limit to 10000 IPs
+        int count = Math.min(end - start + 1, 10000);
