+        
+        int start = bytesToInt(startAddr.getAddress());
+        int end = bytesToInt(endAddr.getAddress());
+        
+        // Limit range to 10000 IPs
+        int count = Math.min(end - start + 1, 10000);
+        
+        for (int i = 0; i < count; i++) {
+            ips.add(intToIp(start + i));
+        }
+        
+        return ips;
+    }
