+                String schemaJson = mapper.writeValueAsString(entry.getValue());
+                Schema<?> schema = io.swagger.v3.core.util.Json.mapper().readValue(schemaJson, Schema.class);
+                schemaDefinitions.put(entry.getKey(), schema);
