+            apiCollectionId,
+            mcpRequest.getPathWithQueryParams(),
+            buildHeaders(host),
+            HttpMethod.POST.name(),
+            mcpRequest.getBody(),
+            new OriginalHttpResponse(jsonrpcResponse, Collections.emptyMap(), HttpStatus.SC_OK)
+        );
