+            if (callbackWasEmpty) {
+                apiCollection.setSseCallbackUrl(DEFAULT_HTTP_CALLBACK_URL);
+                request.setUrl(DEFAULT_HTTP_CALLBACK_URL);
+            }
+            transportType = TRANSPORT_HTTP;
+        }
+
+        return transportType;
+    }
