+            List<ApiInfo.ApiInfoKey> apisList = ((CustomTestingEndpoints) testingEndpoints).getApisList();
+            if (apisList != null) {
+                for (ApiInfo.ApiInfoKey key : apisList) ids.add(key.getApiCollectionId());
