+
+                if(inputStream == null) {
+                    System.err.println("File not found!");
+                    return;
+                }
+
+                String line;
+                while((line = reader.readLine()) != null) {
+                    if(line.length() > 2) dictFilter.put(line.toUpperCase());
+                }
+
+                insertWords(WordListProvider.getTwoLettersWords());
