+        String queryParams = textOrEmpty(reqNode, "queryParams");
+        String method = textOrEmpty(reqNode, "method");
+        if (method.isEmpty()) {
+            method = "GET";
+        }
+        String type = textOrEmpty(reqNode, "type");
+        if (type.isEmpty()) {
