+    public static TestingRun findPendingTestingRun(int delta) {
+
+        Bson filter1 = Filters.and(Filters.eq(TestingRun.STATE, TestingRun.State.SCHEDULED),
+                Filters.lte(TestingRun.SCHEDULE_TIMESTAMP, Context.now())
