+                String fieldName = fieldNames.next();
+                params.add("#"+fieldName);
+                JsonNode fieldValue = node.get(fieldName);
+                extractAllValuesFromPayload(fieldValue, params,values);
+                params.remove(params.size()-1);
+            }
+        }
+
+    }
