+    public static boolean isPossiblyIncompleteJson(String json) {
+        if(json == null || json.isEmpty()) {
+            return false;
+        }
+
+        if ((json.startsWith("{") && !json.endsWith("}")) || (json.startsWith("[") && !json.endsWith("]"))) {
+            return true;
+        }
+        return false;
+    }
