+            if(uri.getPort() != -1){
+                if (uri.getPort() == 80 || uri.getPort() == 443) {
+                    return uri.getScheme() + "://" + uri.getHost() + url;
+                }
+                return uri.getScheme() + "://" + uri.getHost() + ":" + uri.getPort() + url;
