+                int currentDepth = current.getDepth();
+
+                // Find children
+                for (Span span : spans) {
+                    if (currentId.equals(span.getParentSpanId()) && span.getDepth() == 0 && !span.getTraceId().equals(rootSpanId)) {
+                        span.setDepth(currentDepth + 1);
+                        queue.offer(span.getTraceId());
+                    }
+                }
+            }
+        }
+    }
